    "engineeringData": {
      "blockDesign": "Inline 6-cylinder cast iron block providing phenomenal structural rigidity, perfect primary balance, and unmatched durability. This is the very foundation of its 'Diesel 2JZ' reputation, capable of withstanding immense cylinder pressures.",
      "crankshaft": "Forged steel, supported by 7 massive main bearings. Features incredibly precise counterweights to ensure buttery smooth power delivery.",
      "pistonSpeed": "14.2 m/s @ 4600 RPM. Designed specifically for high-compression diesel ignition and extreme longevity under turbocharged loads.",
      "alternator": "90A or 115A Bosch standard unit.",
      "rotatingAssembly": { "pistonConstruction": "Heavy-duty cast aluminum. Highly resistant to wear and capable of handling significant aftermarket boost.", "wristPinDiameter": "28 mm.", "connectingRodLength": "149 mm.", "crankMainJournal": "58.0 mm.", "rodRatio": "1.76" },
      "cylinderHead": { "combustionChamberVol": "DOHC, 4-valve per cylinder (24-valve) with pre-combustion chambers. This massive upgrade over the 12-valve OM603 provides vastly superior airflow dynamics, allowing the engine to breathe exceptionally well at high RPMs.", "intakePortFlow": "Designed for excellent mid-range torque and high-RPM power. Features highly reliable hydraulic lifters.", "valveSizes": "Intake: 28.0 mm / Exhaust: 26.0 mm.", "lifterType": "Maintenance-free hydraulic bucket tappets." },
      "oilAndCooling": { "oilSquirters": "Yes, dedicated oil jets aggressively cool the underside of the massive pistons.", "oilPumpType": "Highly reliable chain-driven gear pump.", "thermostatOpening": "80°C.", "oilCooler": "Air-to-oil cooler mounted alongside the radiator." },
      "fuelSystem": { "systemType": "Bosch EDC Inline Injection Pump (ERE). Mechanically pumps fuel but utilizes electronic governing for precise idle and emissions control.", "maxPressure": "135 Bar opening pressure at the mechanical injectors.", "injectors": "Bosch mechanical pintle-type injectors." },
      "tuningLimits": { "maxSafeTorqueStock": "650 Nm", "maxSafePowerStock": "400 hp", "weakestLink": "The 5-speed automatic transmission limits and the electronic EDC pump restrictive capacity." },
      "electrical": { "coils": "None. Compression ignition.", "ecu": "Bosch Electronic Diesel Control (EDC) managing the injection pump actuator and EGR." }
    },
