    "engineeringData": {
      "blockDesign": "Inline 6-cylinder all-aluminum closed-deck block. This highly updated OM656M block features optimized structural ribbing and ultra-hard NANOSLIDE twin-wire arc-sprayed cylinder linings. It omits all traditional front belt drives, reducing the physical length to accommodate hibrid components.",
      "crankshaft": "Forged steel, supported by 7 massive main bearings. Directly handles the combined torsional stresses of high-pressure combustion and the rear-mounted 48V ISG electric motor.",
      "pistonSpeed": "14.8 m/s @ 4600 RPM. Employs advanced stepped-bowl forged steel pistons inside the aluminum block structure to manage extreme combustion pressure thresholds.",
      "alternator": "None. Power generation is managed by the integrated 48V starter generator assembly which steps down current to feed the baseline 12V grids.",
      "rotatingAssembly": { "pistonConstruction": "Heavy-duty forged steel with internal oil cooling galleries.", "wristPinDiameter": "32 mm.", "connectingRodLength": "150 mm.", "crankMainJournal": "65.0 mm.", "rodRatio": "1.62" },
      "cylinderHead": { "combustionChamberVol": "DOHC, 4-valve per cylinder (24-valve). Features advanced CAMTRONIC variable lift controls on the exhaust camshaft to aggressively manage catalytic light-off values.", "intakePortFlow": "Engineered for rapid swirl generation to maximize fuel-air mixing under intense multi-pulse rail profiles.", "valveSizes": "Intake: 29.0 mm / Exhaust: 27.0 mm.", "lifterType": "Maintenance-free hydraulic bucket tappets." },
      "oilAndCooling": { "oilSquirters": "Yes, dedicated high-pressure jets target the internal cooling galleries of the steel pistons.", "oilPumpType": "Advanced variable-displacement rotary vane pump to minimize parasitic drag.", "thermostatOpening": "100°C (Electronically mapped to assist with rapid SCR warm-up).", "oilCooler": "Massive high-flow water-to-oil heat exchanger." },
      "fuelSystem": { "systemType": "Common Rail Direct Injection (CRDI) generating up to an immense 2700 bar.", "maxPressure": "2700 Bar.", "injectors": "Ultra-fast Piezo-electric design, requiring pristine fuel quality to avoid internal nozzle scoring." },
      "tuningLimits": { "maxSafeTorqueStock": "900 Nm", "maxSafePowerStock": "450 hp", "weakestLink": "The 48V electronic hybrid components, the restrictive Euro 6e filter paths, and the complex software handshakes represent the true ceiling constraints." },
      "electrical": { "coils": "None. Compression ignition.", "ecu": "Bosch MD1 coordinating hibrid energy recuperation, sequential turbo stages, Camtronic lift steps, and multi-stage SCR dosing loops." }
    },
