    "engineeringData": {
      "blockDesign": "Transverse Inline-4 sand-cast aluminum closed-deck block. Rotated 180 degrees compared to the M260 (intake at the front, exhaust at the rear). This allows for a much lower hood line and straighter air intake routing. Features NANOSLIDE cylinder lining and baffled cooling jackets.",
      "crankshaft": "Forged steel, micro-alloyed crankshaft supported by 5 massive main bearings. Hand-assembled under the 'One Man, One Engine' philosophy in Affalterbach.",
      "pistonSpeed": "17.1 m/s @ 7200 RPM. Specialized forged aluminum pistons with deeply optimized cooling galleries.",
      "alternator": "150A Bosch unit with LIN-bus power management.",
      "rotatingAssembly": { "pistonConstruction": "Forged aluminum.", "wristPinDiameter": "22 mm.", "connectingRodLength": "144 mm.", "crankMainJournal": "54.0 mm.", "rodRatio": "1.95" },
      "cylinderHead": { "combustionChamberVol": "DOHC, 4-valve per cylinder (16-valve). Features CAMTRONIC on the exhaust side and enormous sodium-filled exhaust valves.", "intakePortFlow": "Fed by a dual-stage injection system (Direct + Port), keeping valves perfectly clean and maximizing fuel volume.", "valveSizes": "Intake: 34.0 mm / Exhaust: 30.0 mm.", "lifterType": "Maintenance-free hydraulic bucket tappets." },
      "oilAndCooling": { "oilSquirters": "Yes, high-pressure jets target the piston crowns.", "oilPumpType": "Two-stage variable-displacement electronic vane pump.", "thermostatOpening": "Electronically mapped thermal management module with multiple auxiliary electric pumps.", "oilCooler": "Massive dedicated water-to-oil heat exchanger." },
      "fuelSystem": { "systemType": "Dual Injection (CGI + PFI). 200 Bar direct injection piezo injectors + solenoid port injectors in the intake manifold.", "maxPressure": "200 Bar.", "injectors": "4x Piezo (Direct) + 4x Solenoid (Port)." },
      "tuningLimits": { "maxSafeTorqueStock": "550 Nm", "maxSafePowerStock": "500 hp", "weakestLink": "The 8-speed AMG DCT transmission clutch packs will severely slip if torque exceeds 550 Nm without an aftermarket TCU tune. The thermal limits of the engine bay." },
      "electrical": { "coils": "4 individual high-energy coil-on-plug units firing multiple times per stroke.", "ecu": "Bosch MED17.7.7 managing extreme 1.9 bar boost control, dual injection, and AMG exhaust flaps." }
    },
