    "tuningGraphData": { "stock": { "hp": 163, "nm": 400 }, "stage1": { "hp": 210, "nm": 500 }, "stage2": { "hp": 230, "nm": 530 }, "stage3": { "hp": 270, "nm": 580 } },
    "model3DPath": "/images/brands/mercedes/GLK/glk.glb",
